202	void AGBGun::UpdateAimFOV(float DeltaSeconds, bool bInstant)
203	{
204		const AGBPlayerCharacter* Player = GetPlayerOwner();
205		UCameraComponent* Camera = Player ? Player->GetCamera() : nullptr;
206		if (!Camera)
207		{
208			return;
209		}
210	
211		const float Target = bAiming ? 1.f : 0.f;
212		if (AimAlpha == Target)
213		{
214			return;
215		}
216		if (AimAlpha <= 0.f)
217		{
218			HipFOV = Camera->FieldOfView;
219		}
220	
221		if (bInstant)
222		{
223			AimAlpha = Target;
224		}
225		else
226		{
227			const float AimTime = GetStat(GBWeaponStat::AimTime, 0.15f);
228			const float Step = AimTime > KINDA_SMALL_NUMBER ? DeltaSeconds / AimTime : 1.f;
229			AimAlpha = FMath::Clamp(Target > AimAlpha ? AimAlpha + Step : AimAlpha - Step, 0.f, 1.f);
230		}
231		Camera->SetFieldOfView(FMath::Lerp(HipFOV, GetStat(GBStat::AimFOV, HipFOV), AimAlpha));
232	}
