260	
261	bool AGBGun::PerformAttack()
262	{
263		AGBPlayerCharacter* Player = GetPlayerOwner();
264		if (!Player || !GetWorld() || bReloading)
265		{
266			return false;
267		}
268		if (Ammo.InMagazine <= 0)
269		{
270			Reload();
271			return false;
272		}
273	
274		const FGBDamageInfo BaseInfo = MakeDamageInfo();
275		const float SpreadDegrees = GetCurrentSpread();
276	
277		--Ammo.InMagazine;
278	
279		const FGBWeaponDefinition* Def = GetDefinition();
280		if (Def && Def->FireMode.Equals(TEXT("Projectile"), ESearchCase::IgnoreCase))
281		{
282			FireProjectile(BaseInfo, SpreadDegrees);
283		}
284		else
285		{
286			FireHitscan(BaseInfo, SpreadDegrees);
287		}
288	
289		const float RecoilYaw = GetStat(GBStat::RecoilYaw, 0.f);
290		Player->AddRecoil(GetStat(GBStat::RecoilPitch, 0.f), Random.FRandRange(-RecoilYaw, RecoilYaw), GetStat(GBStat::RecoilRecovery, 0.f));
291	
292		NotifyEquipmentChanged();
293	
294		if (Ammo.InMagazine <= 0)
295		{
296			Reload();
297		}
298		return true;
299	}
