301	float AGBGun::GetCurrentSpread() const
302	{
303		const float Base = bAiming ? GetStat(GBStat::AimSpread, 0.f) : GetStat(GBStat::Spread, 0.f);
304		const float Move = bAiming ? GetStat(GBStat::AimMoveSpread, 0.f) : GetStat(GBStat::MoveSpread, 0.f);
305		const AGBPlayerCharacter* Player = GetPlayerOwner();
306		const UCharacterMovementComponent* MoveComp = Player ? Player->GetCharacterMovement() : nullptr;
307		if (!MoveComp)
308		{
309			return FMath::Max(0.f, Base);
310		}
311		// Full bonus at the current max walk speed (already lowered while aiming), so slow aimed steps still count.
312		return UGBCombatLibrary::ComputeMovementSpread(Base, Move, MoveComp->Velocity.Size2D(), MoveComp->MaxWalkSpeed);
313	}
