315	void AGBGun::FireHitscan(const FGBDamageInfo& BaseInfo, float SpreadDegrees)
316	{
317		AGBPlayerCharacter* Player = GetPlayerOwner();
318		UWorld* World = GetWorld();
319	
320		const FVector Origin = Player->GetAimOrigin();
321		const FVector AimDirection = Player->GetAimDirection();
322		const FVector Muzzle = Player->GetMuzzleLocation();
323		const float Range = GetStat(GBStat::Range, 5000.f);
324		const int32 Pellets = FMath::Max(1, FMath::RoundToInt(GetStat(GBStat::Pellets, 1.f)));
325		const float FalloffStart = GetStat(GBStat::FalloffStart, 0.f);
326		const float FalloffEnd = GetStat(GBStat::FalloffEnd, 0.f);
327		const float NearMult = GetStat(GBStat::FalloffNearMult, 1.f);
328		const float FarMult = GetStat(GBStat::FalloffFarMult, 1.f);
329		const float HeadshotMult = GetStat(GBStat::HeadshotMult, 1.f);
330	
331		FCollisionQueryParams Params(SCENE_QUERY_STAT(GBGunTrace), false, Player);
332		Params.AddIgnoredActor(this);
333	
334		for (int32 Index = 0; Index < Pellets; ++Index)
335		{
336			const FVector Direction = UGBCombatLibrary::ApplySpread(AimDirection, SpreadDegrees, Random);
337			const FVector End = Origin + Direction * Range;
338	
339			FHitResult Hit;
340			const bool bHit = World->LineTraceSingleByChannel(Hit, Origin, End, GBWeapon::AimTraceChannel, Params);
341			AActor* Target = bHit ? Hit.GetActor() : nullptr;
342	
343			if (Target && UGBAttributeComponent::Find(Target))
344			{
345				FGBDamageInfo Info = BaseInfo;
346				Info.HitLocation = Hit.ImpactPoint;
347				Info.HitDirection = Direction;
348				Info.Amount *= UGBCombatLibrary::DistanceFalloffMultiplier(Hit.Distance, FalloffStart, FalloffEnd, NearMult, FarMult);
349				UGBCombatLibrary::ApplyWeakPointBonus(Target, Info, HeadshotMult);
350				UGBCombatLibrary::DealDamage(Target, Info);
351			}
352	
353	#if !UE_BUILD_SHIPPING
354			// Placeholder tracer.
355			DrawDebugLine(World, Muzzle, bHit ? Hit.ImpactPoint : End, FColor(255, 220, 120), false, 0.05f, 0, 0.6f);
356	#endif
357		}
358	}
359	
360	void AGBGun::FireProjectile(const FGBDamageInfo& BaseInfo, float SpreadDegrees)
361	{
362		AGBPlayerCharacter* Player = GetPlayerOwner();
363		UWorld* World = GetWorld();
364	
365		const float Range = GetStat(GBStat::Range, 5000.f);
366		const FVector Muzzle = Player->GetMuzzleLocation();
367		FVector AimDirection = (FindAimPoint(Range) - Muzzle).GetSafeNormal();
368		if (AimDirection.IsNearlyZero())
369		{
370			AimDirection = Player->GetAimDirection();
371		}
372	
373		FGBProjectileConfig Config;
374		Config.Damage = BaseInfo;
375		Config.Speed = GetStat(GBStat::ProjectileSpeed, 3000.f);
376		Config.Radius = GetStat(GBStat::ProjectileRadius, 5.f);
377		Config.GravityScale = GetStat(GBStat::ProjectileGravity, 0.f);
378		Config.MaxRange = Range;
379		Config.bPixelArt = false; // art rule: gun shots are 3D
380		Config.Color = GBPlaceholder::ElementColor(static_cast<uint8>(BaseInfo.Element));
381	
382		const int32 Pellets = FMath::Max(1, FMath::RoundToInt(GetStat(GBStat::Pellets, 1.f)));
383		for (int32 Index = 0; Index < Pellets; ++Index)
384		{
385			const FVector Direction = UGBCombatLibrary::ApplySpread(AimDirection, SpreadDegrees, Random);
386			AGBProjectile::SpawnProjectile(World, Config, Muzzle, Direction, Player);
387		}
388	}
