90		const int32 Index = FMath::Clamp(static_cast<int32>(Shape), 0, 4);
91		if (!Cache[Index].IsValid())
92		{
93			static const TCHAR* const Paths[5] =
94			{
95				TEXT("/Engine/BasicShapes/Cube.Cube"),
96				TEXT("/Engine/BasicShapes/Sphere.Sphere"),
97				TEXT("/Engine/BasicShapes/Cylinder.Cylinder"),
98				TEXT("/Engine/BasicShapes/Cone.Cone"),
99				TEXT("/Engine/BasicShapes/Plane.Plane"),
100			};
101			Cache[Index] = LoadObject<UStaticMesh>(nullptr, Paths[Index]);
102			if (!Cache[Index].IsValid())
103			{
104				UE_LOG(LogGB, Warning, TEXT("Placeholder: cannot load mesh %s"), Paths[Index]);
