110	UMaterialInstanceDynamic* GBPlaceholder::SetupShape(UStaticMeshComponent* Component, EGBShape Shape, const FVector& SizeCm, const FLinearColor& Color, bool bGlow)
111	{
112		if (!Component)
113		{
114			return nullptr;
115		}
116	
117		Component->SetStaticMesh(GetShapeMesh(Shape));
118		Component->SetRelativeScale3D(SizeCm / GBPlaceholderPrivate::ShapeSizeCm);
119	
120		UMaterialInterface* BaseMaterial = GBPlaceholderPrivate::GetMaterial(bGlow);
121		if (!BaseMaterial)
122		{
123			return nullptr;
124		}
125	
126		UMaterialInstanceDynamic* Material = UMaterialInstanceDynamic::Create(BaseMaterial, Component);
127		Material->SetVectorParameterValue(GBPlaceholderPrivate::ColorParam, Color);
128		Component->SetMaterial(0, Material);
129		return Material;
130	}
