132	UMaterialInstanceDynamic* GBPlaceholder::SetupTexturedShape(UStaticMeshComponent* Component, EGBShape Shape, const FVector& SizeCm, FName TextureId,
133		float TileSizeCm, const FLinearColor& Tint, bool bGlow)
134	{
135		if (!Component)
136		{
137			return nullptr;
138		}
139	
140		UMaterialInterface* BaseMaterial = GBPlaceholderPrivate::GetPixelSurfaceMaterial();
141		if (!BaseMaterial)
142		{
143			return SetupShape(Component, Shape, SizeCm, Tint);
144		}
145	
146		Component->SetStaticMesh(GetShapeMesh(Shape));
147		Component->SetRelativeScale3D(SizeCm / GBPlaceholderPrivate::ShapeSizeCm);
148	
149		UMaterialInstanceDynamic* Material = UMaterialInstanceDynamic::Create(BaseMaterial, Component);
150		if (UGBPixelSpriteLibrary* Library = UGBPixelSpriteLibrary::Get(Component))
151		{
152			Material->SetTextureParameterValue(GBPlaceholderPrivate::TextureParam, Library->GetTileTexture(TextureId));
153		}
154		else
155		{
156			// Not in a game world yet (the library lives on the game instance): the material's default texture shows.
157			UE_LOG(LogGB, Warning, TEXT("Placeholder: no pixel sprite library for '%s' on %s; using the default texture."),
158				*TextureId.ToString(), *GetNameSafe(Component->GetOwner()));
159		}
160		Material->SetVectorParameterValue(GBPlaceholderPrivate::TintParam, Tint);
161		Material->SetScalarParameterValue(GBPlaceholderPrivate::TileSizeParam, FMath::Max(TileSizeCm, GBPlaceholderPrivate::MinTileSizeCm));
162		Material->SetScalarParameterValue(GBPlaceholderPrivate::GlowParam, bGlow ? 1.f : 0.f);
163		Component->SetMaterial(0, Material);
164		return Material;
165	}
166	
167	void GBPlaceholder::SetShapeColor(UStaticMeshComponent* Component, const FLinearColor& Color)
168	{
169		if (!Component)
170		{
171			return;
172		}
173		if (UMaterialInstanceDynamic* Material = Cast<UMaterialInstanceDynamic>(Component->GetMaterial(0)))
174		{
175			// "Color" on SetupShape materials, "Tint" on SetupTexturedShape ones; the other name is ignored.
176			Material->SetVectorParameterValue(GBPlaceholderPrivate::ColorParam, Color);
177			Material->SetVectorParameterValue(GBPlaceholderPrivate::TintParam, Color);
178		}
179	}
180	
181	UMaterialInstanceDynamic* GBPlaceholder::SetupFlatSprite(UStaticMeshComponent* Component, FName SpriteId, float SizeCm, const FLinearColor& Tint, float Glow)
182	{
183		if (!Component)
184		{
185			return nullptr;
186		}
187	
188		const float SafeSize = FMath::Max(1.f, SizeCm);
189		UMaterialInterface* BaseMaterial = GBPlaceholderPrivate::GetPixelDecalMaterial();
190		if (!BaseMaterial)
191		{
192			return SetupShape(Component, EGBShape::Plane, FVector(SafeSize, SafeSize, 100.f), Tint, true);
193		}
194	
195		Component->SetStaticMesh(GetShapeMesh(EGBShape::Plane));
196		const float Scale = SafeSize / GBPlaceholderPrivate::ShapeSizeCm;
197		Component->SetRelativeScale3D(FVector(Scale, Scale, 1.f));
198	
199		UMaterialInstanceDynamic* Material = UMaterialInstanceDynamic::Create(BaseMaterial, Component);
200		if (UGBPixelSpriteLibrary* Library = UGBPixelSpriteLibrary::Get(Component))
201		{
202			Material->SetTextureParameterValue(GBPlaceholderPrivate::TextureParam, Library->GetSprite(SpriteId));
203		}
204		else
205		{
206			// Not in a game world yet (the library lives on the game instance): the material's default texture shows.
207			UE_LOG(LogGB, Warning, TEXT("Placeholder: no pixel sprite library for '%s' on %s; using the default texture."),
208				*SpriteId.ToString(), *GetNameSafe(Component->GetOwner()));
209		}
210		Material->SetVectorParameterValue(GBPlaceholderPrivate::TintParam, Tint);
211		Material->SetScalarParameterValue(GBPlaceholderPrivate::GlowParam, Glow);
212		Component->SetMaterial(0, Material);
213		return Material;
214	}
215	
216	void GBPlaceholder::SetFlatSpriteLook(UStaticMeshComponent* Component, const FLinearColor& Tint, float Glow)
217	{
218		if (!Component)
219		{
220			return;
221		}
222		if (UMaterialInstanceDynamic* Material = Cast<UMaterialInstanceDynamic>(Component->GetMaterial(0)))
223		{
224			// "Tint"/"Glow" on decal materials; "Color" on the SetupShape fallback (the other names are ignored).
225			Material->SetVectorParameterValue(GBPlaceholderPrivate::TintParam, Tint);
226			Material->SetScalarParameterValue(GBPlaceholderPrivate::GlowParam, Glow);
227			Material->SetVectorParameterValue(GBPlaceholderPrivate::ColorParam, Tint);
228		}
229	}
230	
231	FLinearColor GBPlaceholder::ElementColor(uint8 ElementAsByte)
232	{
233		switch (static_cast<EGBElement>(ElementAsByte))
234		{
235		case EGBElement::Physical:  return FLinearColor(0.55f, 0.55f, 0.55f);
236		case EGBElement::Arcane:    return FLinearColor(0.55f, 0.20f, 1.00f);
237		case EGBElement::Fire:      return FLinearColor(1.00f, 0.40f, 0.05f);
238		case EGBElement::Lightning: return FLinearColor(1.00f, 0.90f, 0.15f);
239		case EGBElement::Ice:       return FLinearColor(0.20f, 0.90f, 1.00f);
240		case EGBElement::Air:       return FLinearColor(0.65f, 1.00f, 0.70f);
241		default:                    return FLinearColor::White;
242		}
243	}
