cd /c/Users/VNasher/AppData/Local/Temp/claude/c1b810ae341cf89c/7c83ebdc-db9f-4d2a-a6cf-83322c35b386/scratchpad; cat > rifle_islands.py <<'EOF'
import bpy, bmesh
ob=[o for o in bpy.context.scene.objects if o.type=='MESH'][0]
bm=bmesh.new(); bm.from_mesh(ob.data); bm.faces.ensure_lookup_table()
seen=set(); isl=[]
for f in bm.faces:
    if f.index in seen: continue
    st=[f]; seen.add(f.index); fs=[]
    while st:
        g=st.pop(); fs.append(g)
        for e in g.edges:
            for h in e.link_faces:
                if h.index not in seen: seen.add(h.index); st.append(h)
    vs={v for g in fs for v in g.verts}
    mn=[min(v.co[i] for v in vs) for i in range(3)]; mx=[max(v.co[i] for v in vs) for i in range(3)]
    isl.append((len(fs),mn,mx))
isl.sort(key=lambda t:-t[0])
print("VERTS",len(bm.verts),"FACES",len(bm.faces),"ISLANDS",len(isl), "UVLAYERS", [l.name for l in ob.data.uv_layers])
for n,mn,mx in isl[:60]:
    print("ISL",n,[round(a,3) for a in mn],[round(a,3) for a in mx])
EOF
