cd /c/GameJam; node -e "
const fs=require('fs');let p='Tools/Blender/rifle_export_fbx.py';let s=fs.readFileSync(p,'utf8');
s=s.split('    bm.to_mesh(me)\n    bm.free()\n    for m in materials:').join('    bm.to_mesh(me)\n    bm.free()\n    # The GLB\\'s custom normals do not survive the bmesh round trip, and every face is smooth-shaded: the hard-surface\n    # gun rendered soft and rounded (owner: \"it looks made of jelly\"). Hard edges above SHARP_ANGLE restore the panels.\n    me.set_sharp_from_angle(angle=math.radians(SHARP_ANGLE))\n    for m in materials:');
s=s.split('TURN = Matrix.Rotation(math.pi / 2, 4, \"Z\")').join('TURN = Matrix.Rotation(math.pi / 2, 4, \"Z\")\nSHARP_ANGLE = 30.0   # degrees: edges sharper than this are shaded hard');
fs.writeFileSync(p,s);
p='Tools/Jam/import_rifle.py';s=fs.readFileSync(p,'utf8');
const a=s.indexOf('    g.out(g.const(0.15, -600, -450), \"\", unreal.MaterialProperty.MP_METALLIC)');
const b=s.indexOf('    return g.node(unreal.MaterialExpressionTextureSample, -1400, -300');
s=s.slice(0,a)+\`    # No ORM in the source: the albedo's brightness tells polymer from metal. Light parts are matte white polymer
    # (roughness ROUGH_POLYMER, not metallic); dark parts are satin metal (ROUGH_METAL, metallic METAL_DARK). One flat
    # value for the whole gun made it read soft and glossy.
    lum = g.node(unreal.MaterialExpressionDotProduct, -1100, -380)
    g.connect(base, \"RGB\", lum, \"A\")
    g.connect(g.node(unreal.MaterialExpressionConstant3Vector, -1300, -300, constant=unreal.LinearColor(0.3, 0.59, 0.11, 1.0)), \"\", lum, \"B\")
    light = g.unary(unreal.MaterialExpressionSaturate,
                    g.mul(g.binary(unreal.MaterialExpressionSubtract, lum, g.const(0.1, -1000, -260), -900, -380),
                          g.const(1.0 / 0.3, -900, -260), -750, -380), -600, -380)
    rough = g.node(unreal.MaterialExpressionLinearInterpolate, -400, -380)
    g.connect(g.const(ROUGH_METAL, -550, -300), \"\", rough, \"A\")
    g.connect(g.const(ROUGH_POLYMER, -550, -240), \"\", rough, \"B\")
    g.connect(light, \"\", rough, \"Alpha\")
    g.out(rough, \"\", unreal.MaterialProperty.MP_ROUGHNESS)
    metal = g.mul(g.unary(unreal.MaterialExpressionOneMinus, light, -450, -460), g.const(METAL_DARK, -450, -520), -300, -480)
    g.out(metal, \"\", unreal.MaterialProperty.MP_METALLIC)
\`+s.slice(b);
s=s.split('ALBEDO_SCALE = 0.8').join('ALBEDO_SCALE = 0.8\nROUGH_POLYMER = 0.68\nROUGH_METAL = 0.36\nMETAL_DARK = 0.6');
fs.writeFileSync(p,s);"
